with gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '30' minute then 1 else 0 end as new_group_flag from device_readings), islands as (select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from gaps) select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, burst_id, case when device_code rlike '^(DV-01|DV-02)$' then 'PRIORITY' when device_code rlike '^(DV-03|DV-04)$' then 'EXTENDED' else 'GROUP_B' end as device_code_zone from islands order by id, temp_c limit 10;
